# Find the smallest cube number expressible as sum of two different positive cubes in two different ways
from collections import defaultdict

limit = 1000  # check cubes up to this base

# Precompute cubes
cubes = {i: i**3 for i in range(1, limit+1)}
cube_set = set(cubes.values())

# For each cube number k^3, find all ways to write it as a^3 + b^3 (a < b)
results = defaultdict(list)

max_val = limit**3
for a in range(1, limit):
    a3 = a**3
    if 2*a3 > max_val:
        break
    for b in range(a+1, limit):
        b3 = b**3
        s = a3 + b3
        if s > max_val:
            break
        results[s].append((a, b))

# Now find entries where s is itself a perfect cube and has >= 2 representations
found = []
for s, pairs in results.items():
    if len(pairs) >= 2:
        # Check if s is a perfect cube
        cr = round(s ** (1/3))
